import type { Transaction } from './transaction.entity';

/**
 * A named place where a User's money sits, holding one Currency (epic: Shared Domain Entities → Wallet).
 * Not here yet: `archivedAt` (F-3). The Balance is not a field — it is derived on read, never stored.
 */
export interface Wallet {
  /** UUID, generated by Postgres. */
  id: string;
  /** The owner. */
  userId: string;
  /** Trimmed, 1–60 characters. Not unique. */
  name: string;
  /** ISO-4217 code of a supported Currency, fixed at creation (AD-2). */
  currency: string;
  /** In minor units of `currency`; may be zero or negative — an Opening Balance is not Income. */
  openingBalanceMinor: bigint;
  createdAt: Date;
  updatedAt: Date;
}

/** What Ledger needs to store a Wallet; the id and timestamps are generated by Postgres. */
export interface NewWallet {
  userId: string;
  name: string;
  currency: string;
  openingBalanceMinor: bigint;
}

/** A Wallet with its Balance and its Transactions, read together from one consistent snapshot. */
export interface WalletDetail {
  wallet: Wallet;
  /** Opening Balance + Σ income − Σ expense, in minor units; derived by the database on every read. */
  balanceMinor: bigint;
  /** Newest `occurredOn` first, ties by newest `createdAt`, then `id` descending. */
  transactions: Transaction[];
}
